package africa.growtogether.platform.eiam.mfa;
import java.nio.charset.StandardCharsets; import java.security.*; import java.util.*; import javax.crypto.*; import javax.crypto.spec.*; import org.springframework.stereotype.Service;
@Service public class MfaCryptoService {private final SecretKey key; private final SecureRandom random=new SecureRandom(); public MfaCryptoService(MfaProperties p){try{byte[] d=MessageDigest.getInstance("SHA-256").digest(p.encryptionKey().getBytes(StandardCharsets.UTF_8));key=new SecretKeySpec(d,"AES");}catch(Exception e){throw new IllegalStateException(e);}}
 public String encrypt(String value){try{byte[] iv=new byte[12];random.nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key,new GCMParameterSpec(128,iv));byte[] out=c.doFinal(value.getBytes(StandardCharsets.UTF_8));byte[] all=new byte[iv.length+out.length];System.arraycopy(iv,0,all,0,iv.length);System.arraycopy(out,0,all,iv.length,out.length);return Base64.getUrlEncoder().withoutPadding().encodeToString(all);}catch(Exception e){throw new IllegalStateException("Unable to encrypt MFA secret.",e);}}
 public String decrypt(String value){try{byte[] all=Base64.getUrlDecoder().decode(value);byte[] iv=Arrays.copyOfRange(all,0,12),data=Arrays.copyOfRange(all,12,all.length);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,iv));return new String(c.doFinal(data),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("Unable to decrypt MFA secret.",e);}}
}
